#!/bin/bash
# Copy the BrewberryPi brand files from the brand's home, tinkerius/brewberrypi
# (brand/ and site/fonts/, generated by its brand/tools/build_brand.py), into
# the device web interface (brewberry-web layer) and the contract stub's
# "app not installed" page (stub/static/). Don't edit the copies by hand:
# change the brand there, then run this again.
#
# Usage: scripts/sync-brand.sh [<checkout of tinkerius/brewberrypi>] [<ref>]
#        (default: a fresh shallow clone of main)
set -euo pipefail

# shellcheck source=scripts/common.sh
. "$(dirname "$0")/common.sh"

BRAND_REPO=https://github.com/tinkerius/brewberrypi.git
WEB=$REPO_ROOT/layer/brewberry-web.rootfs-overlay/usr/lib/brewberry-web/static
WEB_FILES="brand/logo.svg brand/logo-dark.svg brand/logo-stacked.svg brand/logo-stacked-dark.svg
   brand/favicon.svg brand/favicon.ico brand/apple-touch-icon.png
   site/fonts/zilla-slab-medium.woff2 site/fonts/OFL.txt"
STUB=$REPO_ROOT/stub/static
STUB_FILES="brand/logo-stacked.svg brand/logo-stacked-dark.svg brand/favicon.svg brand/favicon.ico
   site/fonts/zilla-slab-medium.woff2 site/fonts/OFL.txt"

src=${1:-}
ref=${2:-}
if [ -z "$src" ]; then
   src=$(mktemp -d)
   trap 'rm -rf "$src"' EXIT
   git clone --quiet --depth 1 "$BRAND_REPO" "$src"
   ref=HEAD
fi
ref=${ref:-$(git -C "$src" rev-parse --abbrev-ref HEAD)}
copy() { # <destination> <files>
   local f
   mkdir -p "$1"
   for f in $2; do
      git -C "$src" show "$ref:$f" > "$1/${f##*/}"
   done
   echo "copied $(wc -w <<< "$2") brand files from $BRAND_REPO@$(git -C "$src" rev-parse --short "$ref") to ${1#"$REPO_ROOT"/}"
}
copy "$WEB" "$WEB_FILES"
copy "$STUB" "$STUB_FILES"
